insert into public.technologies (
  name,
  slug,
  technology_type,
  source_reference,
  last_verified_at,
  is_active
)
select
  name,
  slug,
  technology_type,
  source_reference,
  verified_at,
  true
from technology_seed
on conflict (slug) do update set
  name = excluded.name,
  technology_type = excluded.technology_type,
  source_reference = excluded.source_reference,
  last_verified_at = excluded.last_verified_at,
  is_active = true;

insert into public.knowledge_graph_nodes (
  node_type,
  entity_id,
  name,
  slug,
  description,
  is_active
)
select
  'category',
  ai_categories.id,
  ai_categories.name,
  'category-' || ai_categories.slug,
  ai_categories.description,
  true
from public.ai_categories
on conflict (node_type, entity_id) do update set
  name = excluded.name,
  slug = excluded.slug,
  description = excluded.description,
  is_active = true;

insert into public.knowledge_graph_nodes (
  node_type,
  entity_id,
  name,
  slug,
  description,
  is_active
)
select
  'company',
  companies.id,
  companies.company_name,
  'company-' || companies.slug,
  companies.ai_role,
  true
from public.companies
where companies.source_reference = 'AI Stocks Explorer source taxonomy'
on conflict (node_type, entity_id) do update set
  name = excluded.name,
  slug = excluded.slug,
  description = excluded.description,
  is_active = true;

